// --- THE REPOSITORY (The DB Adapter) ---
class UserRepository {
  // If we change to SQL tomorrow, we ONLY change this file!
  static async findById(id) {
    // return await MongooseUser.findById(id);
    // return await SQL.query('SELECT * FROM users...');
    return { id, name: "Abstracted User" }; // Simulated return
  }
}

// --- THE CONTROLLER (Business Logic) ---
// Notice there is absolutely NO Mongoose or SQL code here.
const getUser = async (req, res) => {
  const userId = req.params.id;

  // The Controller just asks the Repository!
  const user = await UserRepository.findById(userId);

  if (!user) return res.status(404).send();
  res.json(user);
};

console.log("The Repository Pattern protects your app from being 'vendor-locked' into a specific ORM or Database.");
